import{_ as t,a as s,o as i,a4 as o}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Get Admin Permissions","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-permissions-all","title":"Full Access Token","description":"A token whose role grants full access returns the `all` permission type and a single wildcard.","query":"curl -X GET \\"https://your-domain.com/api/admin/permissions\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"permissions\\",\\n    \\"permissionType\\": \\"all\\",\\n    \\"permissions\\": [\\"*\\"]\\n  }\\n]\\n"},{"id":"admin-permissions-custom","title":"Custom Access Token","description":"A token with a restricted role returns the `custom` permission type and the explicit list of granted ACL keys.","query":"curl -X GET \\"https://your-domain.com/api/admin/permissions\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"permissions\\",\\n    \\"permissionType\\": \\"custom\\",\\n    \\"permissions\\": [\\"catalog\\", \\"catalog.products\\", \\"sales.orders\\"]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/navigation/permissions.md","filePath":"api/rest-api/admin/navigation/permissions.md","lastUpdated":1784902076000}'),n={name:"api/rest-api/admin/navigation/permissions.md"};function r(a,e,d,c,p,l){return i(),s("div",null,e[0]||(e[0]=[o('<h1 id="get-admin-permissions" tabindex="-1">Get Admin Permissions <a class="header-anchor" href="#get-admin-permissions" aria-label="Permalink to &quot;Get Admin Permissions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/permissions</code></td><td>GET</td></tr></tbody></table><p>Returns the authenticated token&#39;s effective permissions so you can gate UI up front — show or hide buttons, menus and actions without triggering trial-and-error <code>403</code> responses.</p><p>The response is a one-element array describing the token&#39;s access.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Identifier of the permissions payload (<code>permissions</code>).</td></tr><tr><td><code>permissionType</code></td><td>string</td><td>One of <code>all</code>, <code>custom</code>, or <code>same_as_web</code>.</td></tr><tr><td><code>permissions</code></td><td>array</td><td>The granted ACL keys, or <code>[&quot;*&quot;]</code> for full access.</td></tr></tbody></table><p><code>permissionType</code> semantics:</p><ul><li><code>all</code> — full access. <code>permissions</code> is <code>[&quot;*&quot;]</code>.</li><li><code>custom</code> — <code>permissions</code> lists the explicitly granted ACL keys.</li><li><code>same_as_web</code> — the token follows the admin&#39;s web role; <code>permissions</code> lists the keys that role currently grants.</li></ul><p>In every case the effective <code>permissions</code> are capped by the admin&#39;s role — a token can never do more than its owner admin can currently do.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A request without a valid token returns <code>401 Unauthorized</code>.</p><p>All admin endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',12)]))}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
